CREATE TABLE ai_recommendation_jobs (job_id BIGINT NOT NULL PRIMARY KEY,user_id BIGINT NOT NULL,target_trip_id BIGINT NULL,request_type VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,region_code VARCHAR(5) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,companion_type VARCHAR(30) NOT NULL,pace VARCHAR(30) NOT NULL,themes JSON NOT NULL,saved_place_ids JSON NOT NULL,wishlist_place_ids JSON NOT NULL,existing_schedule JSON NOT NULL,allow_additional_recommendations BOOLEAN NOT NULL,requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,started_at DATETIME NULL,completed_at DATETIME NULL,expired_at DATETIME NULL,error_code VARCHAR(100) NULL,error_message VARCHAR(255) NULL,error_retryable BOOLEAN NULL,CONSTRAINT fk_ai_job_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,CONSTRAINT fk_ai_job_trip FOREIGN KEY(target_trip_id) REFERENCES trips(trip_id) ON DELETE SET NULL,CONSTRAINT ck_ai_job_request_type CHECK(request_type IN ('GENERAL','SAVED_PLACES','TRIP_WISHLIST')),CONSTRAINT ck_ai_job_status CHECK(status IN ('QUEUED','PROCESSING','SUCCEEDED','FAILED','EXPIRED')));
CREATE INDEX idx_ai_job_user_requested ON ai_recommendation_jobs(user_id,requested_at);
